import{_ as e,o as t,c as s,a6 as r}from"./chunks/framework.BBIckNDn.js";const c=JSON.parse('{"title":"第4部 演習 — ゲームプログラミングパターン","description":"","frontmatter":{"title":"第4部 演習 — ゲームプログラミングパターン","study":{"source":"C++ Wiki","kind":"演習","status":"既存原稿","summary":"正誤を判定し、誤りは訂正してください。 Event QueueはObserverと違い、発行者と購読者の「時間的結合」を切る。 ECSはComponentパターンの改良版であり、常に上位互換である。"}},"headers":[],"relativePath":"game/patterns/exercises.md","filePath":"game/patterns/exercises.md"}'),i={name:"game/patterns/exercises.md"};function l(n,a,o,p,h,d){return t(),s("div",null,[...a[0]||(a[0]=[r(`<h1 id="第4部-演習-—-ゲームプログラミングパターン" tabindex="-1">第4部 演習 — ゲームプログラミングパターン <a class="header-anchor" href="#第4部-演習-—-ゲームプログラミングパターン" aria-label="Permalink to &quot;第4部 演習 — ゲームプログラミングパターン&quot;">​</a></h1><h2 id="問1-概念確認" tabindex="-1">問1. 概念確認 <a class="header-anchor" href="#問1-概念確認" aria-label="Permalink to &quot;問1. 概念確認&quot;">​</a></h2><p>正誤を判定し、誤りは訂正してください。</p><ol><li>Event QueueはObserverと違い、発行者と購読者の「時間的結合」を切る。</li><li>ECSはComponentパターンの改良版であり、常に上位互換である。</li><li>Object Poolは使わない間もメモリを占有する。</li><li>Behavior Treeは毎フレーム根から評価するため、遷移を書かなくても優先度の割り込みが起きる。</li><li>Service LocatorはDIと違い、依存がクラスのシグネチャに現れる。</li></ol><details><summary>解答</summary><ol><li><strong>正</strong>(<a href="/study/game/patterns/event-queue-and-pubsub.html">Event Queue</a>)。2. <strong>誤</strong>。動機が別(柔軟性vs性能)で、少数の複雑なオブジェクトにはComponentが向く(<a href="/study/game/patterns/component-and-ecs.html">Component と ECS</a>)。3. <strong>正</strong>。それがプールの代償(<a href="/study/game/patterns/object-pool.html">Object Pool</a>)。4. <strong>正</strong>(<a href="/study/game/patterns/behavior-tree-and-blackboard.html">Behavior Tree</a>)。5. <strong>誤</strong>。逆。シグネチャに現れるのはDI(<a href="/study/game/patterns/service-locator-and-di.html">Service LocatorとDI</a>)。</li></ol></details><h2 id="問2-コード読解" tabindex="-1">問2. コード読解 <a class="header-anchor" href="#問2-コード読解" aria-label="Permalink to &quot;問2. コード読解&quot;">​</a></h2><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">while</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (accumulator </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> kFixedDt) { </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">FixedUpdate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(kFixedDt); accumulator </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> kFixedDt; }</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Render</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(accumulator </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> kFixedDt);</span></span></code></pre></div><ol><li><code>Render</code> の引数は何のために使いますか。</li><li>このループに上限を付けないと何が起きますか。</li></ol><details><summary>解答</summary><ol><li>補間係数。固定更新の「間」の時刻での見た目を、前回と今回の状態の補間で描き、カクつきを防ぐ。2. 更新1回に1/60秒以上かかるマシンでaccumulatorが増え続け、消化しようとするほど遅くなる「死のスパイラル」(<a href="/study/game/patterns/game-loop-and-update.html">Game Loop</a>)。</li></ol></details><h2 id="問3-問題のあるコードの改善" tabindex="-1">問3. 問題のあるコードの改善 <a class="header-anchor" href="#問3-問題のあるコードの改善" aria-label="Permalink to &quot;問3. 問題のあるコードの改善&quot;">​</a></h2><p>「被弾のたびに <code>Instantiate(damagePopupPrefab)</code>、表示終了で <code>Destroy</code>。連続ヒットするとフレーム落ちし、GCスパイクも出る」— 適用すべきパターンと実装上の注意点2つ(状態リセット/参照の無効化)を説明してください。</p><details><summary>解答の要点</summary><p><a href="/study/game/patterns/object-pool.html">Object Pool</a>。注意点: (1) 再利用時のリセット漏れ(前の表示テキスト・アニメ進行が残る)→ Acquire時に完全初期化。(2) 貸出先が持つ参照のstale化 → 表示終了は必ずプール経由で返し、外部が長期保持しない設計に(必要なら世代ハンドル)。加えてUnityなら<code>SetActive</code>切替とCanvas再構築コストにも注意。</p></details><h2 id="問4-設計比較" tabindex="-1">問4. 設計比較 <a class="header-anchor" href="#問4-設計比較" aria-label="Permalink to &quot;問4. 設計比較&quot;">​</a></h2><p>「敵AI(雑魚30種、ボス3種)」に (a) enum+switchのFSM、(b) Stateパターン、(c) Behavior Tree を検討します。「雑魚は3状態で共通、ボスは10種類以上の行動と優先度割り込みあり」という条件で構成を提案してください。</p><details><summary>解答の要点</summary><p>雑魚: 共通の3状態FSM(enum+switch)を1つ書き、パラメータ(<a href="/study/game/patterns/type-object-and-sandbox.html">Type Object</a>)で個性を出す——30種にクラス階層やBTは過剰。ボス: <a href="/study/game/patterns/behavior-tree-and-blackboard.html">BT</a>(優先度と割り込みの仕様に一致)+実行中の動作は小さなFSM。<strong>「全部同じ仕組みに統一」しないのが正解</strong>という点が本問の狙い。</p></details><h2 id="問5-デバッグ問題" tabindex="-1">問5. デバッグ問題 <a class="header-anchor" href="#問5-デバッグ問題" aria-label="Permalink to &quot;問5. デバッグ問題&quot;">​</a></h2><p>Pub/Subバス導入後、「アイテム取得イベントで所持数UIが更新されるはずが、たまに1個ズレる」報告。調査手順を3ステップで書いてください。</p><details><summary>解答の要点</summary><p>(1) イベントに積んだ値の確認: 発行時に「取得後の総数」ではなく「取得数」を積み、購読側が古い状態と合算していないか(遅延配送では<strong>必要な値を全部積む</strong>鉄則 → <a href="/study/game/patterns/event-queue-and-pubsub.html">Event Queue</a>)。(2) 二重購読の確認: 画面の開閉で購読が重複していないか(<a href="/study/design/patterns/observer.html">Observer</a>の多重実行)。(3) 配送タイミングの確認: UI更新がイベント処理より先に走るフレーム順序になっていないか。——「バスは追跡性が最悪」という欠点への実践的回答として、イベントログ(全発行の記録)を最初に仕込むのも正解。</p></details><h2 id="問6-説明問題" tabindex="-1">問6. 説明問題 <a class="header-anchor" href="#問6-説明問題" aria-label="Permalink to &quot;問6. 説明問題&quot;">​</a></h2><p>「StateとStrategyって同じ構造ですよね? なぜ別の名前なんですか?」への回答を3文以内で書いてください。</p><details><summary>解答例</summary><p>構造(振る舞いオブジェクトへの委譲)は同じで、違いは<strong>変わり方の意味</strong>にある。Stateは「時間とともに自分で遷移する状況」を表し、状態自身が次の状態を決める。Strategyは「外部から与えられたやり方」で、装着後は自分では変わらない——だから設計意図を伝える名前が分かれている(<a href="/study/game/patterns/state-machines.html">ステートマシン</a>)。</p></details><h2 id="問7-小規模実装問題" tabindex="-1">問7. 小規模実装問題 <a class="header-anchor" href="#問7-小規模実装問題" aria-label="Permalink to &quot;問7. 小規模実装問題&quot;">​</a></h2><p>以下から1つ選んで実装してください(いずれもsamples/に出発点あり)。</p><ol><li><a href="/study/samples/cpp/event_queue.cpp">samples/event_queue.cpp</a>: SE再生要求の同フレーム重複除去を追加</li><li><a href="/study/samples/cpp/behavior_tree.cpp">samples/behavior_tree.cpp</a>: 「逃げる」最優先枝の追加</li><li><a href="/study/samples/cpp/object_pool.cpp">samples/object_pool.cpp</a>: 世代付きハンドルの追加</li><li><a href="/study/samples/cpp/fsm_guard.cpp">samples/fsm_guard.cpp</a>: Search状態の追加</li></ol><details><summary>評価基準</summary><p>動くことに加えて: (1) 追加機能の変更が既存コードのどこまで波及したか(パターンの分離が効いたか)を一言で説明できる。(2) 「この規模ならパターンなしでも書けたか?」に答えられる。(3) 所有権(誰がオブジェクトの寿命を管理するか)が曖昧になっていない。</p></details><hr><p>前: <a href="/study/game/patterns/reactive-and-message-bus.html">Reactive Programming</a> | <a href="/study/game/patterns/">カテゴリ目次</a> | <a href="/study/languages/cpp/">第5部: C++の言語機能へ</a></p>`,27)])])}const u=e(i,[["render",l]]);export{c as __pageData,u as default};
